                            text: '<>\n      <Card\n        size="small"\n        title={<EnumTag label="模拟器详情" type="online" value={online} />}\n        extra={\n          <Fragment>\n            <Select\n              placeholder="请选择"\n              value={`设备序号${equipNumber}`}\n              onChange={setEquipNumber}\n              style={{ marginLeft: 20, width: 150 }}\n            >\n              {getControllerList().map(item => {\n                return (\n                  <Option key={item.key} value={item.key}>\n                    {`设备序号${item.value}`}\n                  </Option>\n                )\n              })}\n            </Select>\n\n            {client?.status === SimulatorStatus.CONNECTED ? (\n              <Button type="primary" onClick={disconnectLink}>\n                断开连接\n              </Button>\n            ) : (\n              <Button type="primary" onClick={connectLink} loading={connectLoading}>\n                开始连接\n              </Button>\n            )}\n          </Fragment>\n        }\n      >\n        <Descriptions\n          columns={baseInfoColumns}\n          data={{\n            productDetail: initData.productDetail,\n            version,\n            productType: new ServiceType(deviceType),\n            equipNumber\n          }}\n        />\n      </Card>\n      {services?.length ? (\n        <Collapse\n          defaultActiveKey={services\n            .map(item => {\n              return String(item.iid)\n            })\n            .concat(\'bindInfo\')}\n        >\n          <Collapse.Panel\n            extra={\n              paringInfo && online && <BindUser client={client} paringInfo={paringInfo} resetCallback={setParingInfo} />\n            }\n            header="设备绑定"\n            key="bindInfo"\n          >\n            {paringInfo && online ? (\n              <div style={{ textAlign: \'center\' }}>\n                <QRCode value={paringInfo} size={180} fgColor="#000000" />\n              </div>\n            ) : (\n              <Alert message="提示" description="请先连接模拟设备后再绑定用户" type="warning" showIcon />\n            )}\n          </Collapse.Panel>\n          {services.map((item: ServiceImage) => {\n            return (\n              <Collapse.Panel\n                key={String(item.iid)}\n                header={`${item.iid} ${item.description?.get(Spec.ZH_CN) || \'\'} (${item.type?.name})`}\n              >\n                <ServicePanel\n                  service={item}\n                  onPropertyChange={(p: Property) => {\n                    handleItemChange(p, item.iid)\n                  }}\n                  client={client}\n                  onEventChange={(evt: Event) => {\n                    handleItemChange(evt, item.iid)\n                  }}\n                  onActionChange={(action: Action) => {\n                    handleItemChange(action, item.iid)\n                  }}\n                />\n              </Collapse.Panel>\n            )\n          })}\n        </Collapse>\n      ) : null}\n    </>'
